import re

query = inputs.get('query') or inputs.get('target') or inputs.get('text') or ''
query = str(query).strip()
if not query:
    raise ValueError('query is required')

text = query.lower()


def safe_int(value, default):
    try:
        if value is None or value == '':
            return default
        value = int(value)
        return value if value > 0 else default
    except Exception:
        return default


def parse_number(value):
    value = str(value or '').strip()
    if value.isdigit():
        return int(value)
    digits = {
        '零': 0, '〇': 0, '一': 1, '二': 2, '两': 2, '三': 3, '四': 4,
        '五': 5, '六': 6, '七': 7, '八': 8, '九': 9,
    }
    if value in digits:
        return digits[value]
    if value == '十':
        return 10
    if '十' in value:
        left, _, right = value.partition('十')
        tens = digits.get(left, 1) if left else 1
        ones = digits.get(right, 0) if right else 0
        return tens * 10 + ones
    return 0


def infer_days(default):
    explicit = inputs.get('search_window_days')
    explicit_value = safe_int(explicit, default) if explicit not in (None, '') else None

    # If the caller only provided the default, natural-language time in query wins.
    if explicit_value is None or explicit_value == default:
        if any(term in query for term in ['今天', '今日']) or 'today' in text:
            return 1
        if any(term in query for term in ['昨天', '昨日']) or 'yesterday' in text:
            return 2

        m = re.search(
            r'(?:近|最近|过去|过去的|最近的|近来)?\s*'
            r'([0-9]+|[零〇一二两三四五六七八九十]+)\s*'
            r'(天|日|周|星期|个月|月|年)',
            query,
        )
        if m:
            number = parse_number(m.group(1))
            unit = m.group(2)
            if number > 0:
                if unit in ('天', '日'):
                    return number
                if unit in ('周', '星期'):
                    return number * 7
                if unit in ('个月', '月'):
                    return number * 30
                if unit == '年':
                    return number * 365

        if any(term in query for term in ['最近一周', '近一周', '近7天', '近七天']):
            return 7
        if any(term in query for term in ['近半月', '最近半月', '近15天', '近十五天']):
            return 15
        if any(term in query for term in ['最近', '最新', '近期']) or 'latest' in text or 'recent' in text:
            return 30
        if any(term in query for term in ['今年', '本年']):
            return 365
        if any(term in query for term in ['全部威胁情报', '全部的威胁情报', '所有威胁情报', '所有的威胁情报', '全部历史威胁情报', '不限时间', '不限制时间', '不设时间窗口', '无视时间窗口', '无时间限制']):
            return 3650

    if explicit_value is not None:
        return explicit_value
    return default


def normalize_sources(value):
    aliases = {
        'darkweb': 'darkweb', 'dark web': 'darkweb', '暗网': 'darkweb', 'onion': 'darkweb',
        'telegram': 'telegram', 'tg': 'telegram', '电报': 'telegram',
        'web': 'web', 'public web': 'web', '公开网': 'web', '网页': 'web',
        '新闻': 'web', '公告': 'web', '报告': 'web', 'osint': 'web',
    }
    if isinstance(value, str):
        parts = [x.strip() for x in re.split(r'[,，、\s]+', value) if x.strip()]
    else:
        parts = list(value or [])
    out = []
    for item in parts:
        key = str(item).strip().lower()
        source = aliases.get(key, key)
        if source in ('darkweb', 'telegram', 'web') and source not in out:
            out.append(source)
    return out


def infer_sources(default):
    explicit = inputs.get('include_sources')
    explicit_sources = normalize_sources(explicit) if explicit not in (None, '') else []
    if explicit_sources and set(explicit_sources) != set(default):
        return explicit_sources
    if any(term in query for term in ['全网', '多源', '综合', '全部来源']):
        return default
    mentioned = []
    checks = [
        ('darkweb', ['暗网', 'dark web', 'darkweb', 'onion', '泄露论坛', '勒索站']),
        ('telegram', ['Telegram', 'telegram', 'TG', 'tg', '电报']),
        ('web', ['公开网', '网页', '新闻', '公告', '报告', 'web', 'public web', 'OSINT', 'osint']),
    ]
    for source, terms in checks:
        if any(term in query or term.lower() in text for term in terms):
            mentioned.append(source)
    return mentioned or explicit_sources or default


def infer_report_language(default):
    explicit = inputs.get('report_language')
    if explicit and explicit != default:
        return explicit
    if 'in english' in text or any(term in query for term in ['英文报告', '用英文']):
        return 'en'
    if any(term in query for term in ['中文报告', '用中文']):
        return 'zh-CN'
    return explicit or default


def infer_keyword_languages(default):
    explicit = inputs.get('keyword_languages')
    explicit_langs = []
    if explicit:
        if isinstance(explicit, str):
            explicit_langs = [x.strip() for x in re.split(r'[,，、\s]+', explicit) if x.strip()]
        else:
            explicit_langs = list(explicit)
        if explicit_langs and explicit_langs != default:
            return explicit_langs
    if any(term in query for term in ['只用中文', '中文关键词']):
        return ['zh-CN']
    if any(term in query for term in ['中英文', '中文和英文']):
        return ['zh-CN', 'en']
    return explicit_langs or default


def infer_depth():
    if any(term in query for term in ['快速', '简单', '先看看']):
        return 'quick'
    if any(term in query for term in ['深入', '全面', '尽可能多', '详细']):
        return 'deep'
    return 'normal'


valid_sources = {'darkweb', 'telegram', 'web'}
default_sources = ['darkweb', 'telegram', 'web']
include_sources = [s for s in infer_sources(default_sources) if s in valid_sources] or default_sources
search_window_days = infer_days(30)
report_language = infer_report_language('zh-CN')
keyword_languages = infer_keyword_languages(['zh-CN', 'en', 'ru', 'fa-IR'])
depth = infer_depth()

limit_default = 50
timeout_default = 1200
if depth == 'quick':
    limit_default = 20
    timeout_default = 600
elif depth == 'deep':
    limit_default = 100
    timeout_default = 1800

limit = safe_int(inputs.get('limit') or inputs.get('limit_per_source'), limit_default)
timeout_seconds = safe_int(inputs.get('timeout_seconds'), timeout_default)
pipeline = {
    'query': query,
    'search_window_days': search_window_days,
    'report_language': report_language,
    'keyword_languages': keyword_languages,
    'timeout_seconds': timeout_seconds,
    'include_sources': include_sources,
    'limit': limit,
    'web_limit': safe_int(inputs.get('web_limit') or inputs.get('limit_per_source'), limit),
    'darkweb_limit': safe_int(inputs.get('darkweb_limit') or inputs.get('limit_per_source'), limit),
    'inferred_depth': depth,
}
outputs['pipeline'] = pipeline
outputs['query'] = query

import json
import re

# Inputs --------------------------------------------------------------
noise_input = inputs.get('noise_input') or {
    'query': inputs.get('query'),
    'pipeline': inputs.get('pipeline') or {},
    'search_window_days': (inputs.get('pipeline') or {}).get('search_window_days'),
    'results_by_source': inputs.get('results_by_source') or {},
}
query = noise_input.get('query') or inputs.get('query') or ''
pipeline = inputs.get('pipeline') or noise_input.get('pipeline') or {}
results_by_source = noise_input.get('results_by_source') or {}
if not isinstance(results_by_source, dict):
    results_by_source = {}

# Phase 1: flatten 3-source results into stable-ID event list ---------
all_events = []
source_coverage = {}
for source in ('darkweb', 'telegram', 'web'):
    block = results_by_source.get(source) or {}
    source_coverage[source] = block.get('status') or 'not_provided'
    for r in (block.get('results') or []):
        if not isinstance(r, dict):
            continue
        all_events.append({'id': len(all_events), 'source': source, 'full': r})

# Phase 2: Python-side URL-based dedup. Same URL across sources = same event,
# merge into the first occurrence; later ones become secondaries.
primary_by_url = {}
duplicates = {}
for e in all_events:
    url = (e['full'].get('url') or '').strip()
    if not url:
        continue
    if url in primary_by_url:
        duplicates[e['id']] = primary_by_url[url]
    else:
        primary_by_url[url] = e['id']

# Phase 3: build slim payload (scheme B) for the LLM noise filter.
# - darkweb / web: title (redacted, capped 120 chars)
# - telegram: first 80 chars of summary (the chat-title field is useless for
#   per-message relevance because it is shared across all messages of one chat)
def _redact(s):
    if not isinstance(s, str):
        return ''
    s = re.sub(r'https?://\S+', '[LINK]', s)
    s = re.sub(r'\.onion\S*', '[ONION]', s)
    s = re.sub(r't\.me/\S+', '[TG]', s)
    return s

def _parse_evidence_tags(evidence_str):
    tags = {}
    for part in (evidence_str or '').split(';'):
        if '=' in part:
            k, _, v = part.partition('=')
            k = k.strip(); v = v.strip()
            if k and v:
                tags[k] = v
    return tags

slim_items = []
for e in all_events:
    if e['id'] in duplicates:
        continue  # secondaries don't need the LLM's opinion; Python merges them
    full = e['full']
    item = {'id': e['id'], 'source': e['source']}
    if e['source'] == 'telegram':
        item['text'] = _redact(full.get('summary') or '')[:80]
    else:
        item['title'] = _redact(full.get('title') or '')[:120]
        tags = _parse_evidence_tags(full.get('evidence') or '')
        if tags.get('industry'):
            item['industry'] = tags['industry']
        if tags.get('category'):
            item['category'] = tags['category']
        summary_red = _redact(full.get('summary') or '')[:100]
        if summary_red:
            item['summary'] = summary_red
    slim_items.append(item)

# Phase 4: ask the LLM filter agent. Graceful fallback if it errors / refuses.
noise_ids = set()
agent_text = ''
agent_error = None
agent_succeeded = False
if slim_items:
    payload = {'query': query, 'items': slim_items}
    prompt = (
        'TASK: Classify which items are noise for the given query. '
        'Return JSON only: {"noise_ids": [int, ...]}.\n'
        'INPUT:\n' + json.dumps(payload, ensure_ascii=False)
    )
    res = tool.run_safe(
        'delegate_task',
        subagent_type='noise-reduction-agent',
        category='',
        session_id='',
        command='threat-intel-noise-filter',
        load_skills=[],
        description='Noise filter for threat-intel candidate list',
        prompt=prompt,
    )
    agent_text = res.get('text') or ''
    agent_error = res.get('error')
    if agent_text and not agent_error:
        s = agent_text.strip()
        obj = None
        try:
            obj = json.loads(s)
        except Exception:
            start = s.find('{')
            if start >= 0:
                try:
                    obj, _ = json.JSONDecoder().raw_decode(s, start)
                except Exception:
                    obj = None
        if isinstance(obj, dict) and isinstance(obj.get('noise_ids'), list):
            for nid in obj['noise_ids']:
                if isinstance(nid, int) and 0 <= nid < len(all_events):
                    noise_ids.add(nid)
            agent_succeeded = True

# Phase 5: build deduped_events from full data --------------------------
def _infer_event_type(full):
    title = (full.get('title') or '').lower()
    url = (full.get('url') or '').lower()
    evidence = (full.get('evidence') or '').lower()
    if 'ransomware' in title or 'ransomware' in url or 'ransom' in evidence:
        return 'ransomware'
    if 'leak' in title or 'database' in title or '泄露' in title:
        return 'data_leak'
    if 'credential' in title or 'creds' in title:
        return 'credential_exposure'
    if re.search(r'\bcve-\d{4}-\d+\b', title) or 'vulnerability' in title or 'cve=' in evidence:
        return 'vulnerability'
    if 'access' in title and ('sale' in title or 'sell' in title or 'sold' in title):
        return 'access_sale'
    return 'unknown'

_SEVERITY_RE = re.compile(r'severity=(\w+)', re.I)
def _infer_risk(full, event_type):
    m = _SEVERITY_RE.search(full.get('evidence') or '')
    sev = (m.group(1).lower() if m else '')
    if event_type == 'ransomware' or sev == 'critical':
        return 'critical'
    if event_type in ('data_leak', 'credential_exposure', 'access_sale') or sev == 'high':
        return 'high'
    if event_type == 'vulnerability' or sev == 'medium':
        return 'medium'
    return 'low'

def _evidence_dict(full, src):
    return {
        'source': src,
        'url': full.get('url') or '',
        'time': full.get('time') or '',
        'title': full.get('title') or '',
        'evidence': full.get('evidence') or '',
        'confidence': full.get('confidence') or 'medium',
    }

deduped_events = []
event_by_primary = {}
discarded_items = []

for e in all_events:
    full = e['full']
    src = e['source']
    if e['id'] in noise_ids:
        discarded_items.append({
            'source': src,
            'title': full.get('title') or '',
            'url': full.get('url') or '',
            'reason': 'classified as noise by filter agent',
        })
        continue

    primary_id = duplicates.get(e['id'], e['id'])
    if primary_id != e['id']:
        idx = event_by_primary.get(primary_id)
        if idx is None:
            # primary itself was discarded as noise; drop this duplicate too
            discarded_items.append({
                'source': src,
                'title': full.get('title') or '',
                'url': full.get('url') or '',
                'reason': 'duplicate of an event already classified as noise',
            })
            continue
        primary = deduped_events[idx]
        if src not in primary['sources']:
            primary['sources'].append(src)
        primary['evidence'].append(_evidence_dict(full, src))
        for u in (full.get('sample_urls') or []):
            if isinstance(u, str) and u and u not in primary['raw_refs']:
                primary['raw_refs'].append(u)
        continue

    etype = _infer_event_type(full)
    risk = _infer_risk(full, etype)
    confidence = full.get('confidence') or 'medium'
    deduped_events.append({
        'id': 'event_' + str(e['id']),
        'title': full.get('title') or '',
        'event_type': etype,
        'target': query,
        'time': full.get('time') or '',
        'sources': [src],
        'primary_url': full.get('url') or '',
        'summary': full.get('summary') or '',
        'evidence': [_evidence_dict(full, src)],
        'confidence': confidence,
        'confidence_reason': '基于 ' + src + ' 单源 ' + confidence + ' 命中',
        'risk_level': risk,
        'risk_reason': '依据事件类型 ' + etype + ' 与严重度推断为 ' + risk,
        'raw_refs': [u for u in (full.get('sample_urls') or []) if isinstance(u, str) and u],
    })
    event_by_primary[e['id']] = len(deduped_events) - 1

# Phase 6: aggregate top-level risk + notes ----------------------------
_RANK = {'low': 0, 'medium': 1, 'high': 2, 'critical': 3}
overall_risk = 'low'
for ev in deduped_events:
    if _RANK.get(ev['risk_level'], 0) > _RANK[overall_risk]:
        overall_risk = ev['risk_level']

notes = []
if not slim_items:
    notes.append('No source results to evaluate.')
elif not agent_succeeded:
    detail = agent_error or 'agent did not return a valid {"noise_ids": [...]} object'
    notes.append('Noise filter agent did not deliver a usable verdict; keeping all non-duplicate events. Detail: ' + str(detail))
elif noise_ids:
    notes.append('Filter agent discarded ' + str(len(noise_ids)) + ' item(s) as noise.')

if duplicates:
    notes.append('Python URL-dedup merged ' + str(len(duplicates)) + ' duplicate occurrence(s) into primary events.')

if not deduped_events:
    overall_confidence_reason = '所有源均无可保留的事件'
else:
    overall_confidence_reason = '共 ' + str(len(deduped_events)) + ' 条事件经噪音过滤与 URL 去重后保留'

outputs['query'] = query
outputs['pipeline'] = pipeline
outputs['noise_result'] = {
    'deduped_events': deduped_events,
    'source_coverage': source_coverage,
    'risk_level': overall_risk if deduped_events else 'low',
    'confidence_reason': overall_confidence_reason,
    'discarded_items': discarded_items,
    'notes': notes,
}
outputs['noise_text'] = agent_text
outputs['noise_status'] = 'completed' if (agent_succeeded or not slim_items) else 'partial'
